package com.privatezero.stadiumpad;
import java.util.*;import static com.privatezero.stadiumpad.Data.*;import static com.privatezero.stadiumpad.Models.*;
final class Reorder {
 final State before;final Context context;final int to;final Object bindings;
 Reorder(State s,Context c,int target,Map<Integer,Model> models)throws Exception{before=s;context=c;to=target;c.verify(s);require(c.slot==0&&c.pos%14>=1&&c.pos%14<=12&&target>=0&&target<28&&target%14>=1&&target%14<=12&&target/14==c.pos/14&&target!=c.pos,"Drag within one effect row");int lo=Math.min(c.pos,to),hi=Math.max(c.pos,to);for(Block b:s.blocks)if(b.path==c.path&&b.pos>=lo&&b.pos<=hi){Model m=models.get(b.model);require(m!=null&&m.io.isEmpty()&&!Arrays.asList("split","join").contains(m.category),"Inputs/outputs/routing nodes stay fixed");}if(c.pos>=14){List<Integer> links=new ArrayList<>();for(Object flow:arr(get(s.edit,"sfg_","flow"))){List<Object>a=arr(get(flow,"blks"));for(int i=1;i<a.size();i+=2)if(n(get(a.get(i),"bflw"))==c.path&&n(get(a.get(i),"bblk"))>=14)links.add(n(get(a.get(i),"bblk")));}require(links.size()==1&&lo>=Math.max(15,links.get(0)),"Use desktop editor for this branch layout");}bindings=binding(s);}
 static Object binding(State s){Map<String,Object> ent=new LinkedHashMap<>(obj(get(s.edit,"cg__","entt")));String[][] sets={{"srcs","id__","byps"},{"ctrl","cid_","togl"},{"trgs","id__",""},{"snps","si__",""},{"cmnd","cid_","togl"},{"ctm_","id__",""}};for(String[] set:sets){Object original=ent.get(set[0]);if(!(original instanceof List))continue;List<Object> values=new ArrayList<>();boolean keyed=true;for(Object raw:arr(original)){Map<String,Object> v=new LinkedHashMap<>(obj(raw));if(!set[2].isEmpty())v.remove(set[2]);values.add(v);keyed&=get(v,set[1]) instanceof Number;}if(keyed)values.sort(Comparator.comparingInt(v->n(get(v,set[1]))));ent.put(set[0],values);}Map<String,Object> ctm=new LinkedHashMap<>(obj(ent.get("ctm_")));if(ctm.get("stid") instanceof List){List<Object> ids=new ArrayList<>(arr(ctm.get("stid")));ids.sort(Comparator.comparingInt(Data::n));ctm.put("stid",ids);ent.put("ctm_",ctm);}Map<String,Object> sm=new LinkedHashMap<>(obj(ent.get("sm__")));List<Object> mapping=arr(sm.get("scid"));if(sm.get("scid") instanceof List&&mapping.size()%2==0){TreeMap<Integer,Object> sorted=new TreeMap<>();for(int i=0;i<mapping.size();i+=2)sorted.put(n(mapping.get(i)),mapping.get(i+1));List<Object> joined=new ArrayList<>();for(Map.Entry<Integer,Object> e:sorted.entrySet()){joined.add(e.getKey());joined.add(e.getValue());}sm.put("scid",joined);ent.put("sm__",sm);}return ent;}
 int position(Block b){int p=b.pos;if(b.path==context.path&&p>=Math.min(context.pos,to)&&p<=Math.max(context.pos,to))return p==context.pos?to:p+(context.pos<to?-1:1);return p;}
 boolean matches(State after){if(after.blocks.size()!=before.blocks.size()||!deep(bindings,binding(after)))return false;for(Block old:before.blocks){int pos=old.pos;if(old.path==context.path&&pos>=Math.min(context.pos,to)&&pos<=Math.max(context.pos,to)){if(pos==context.pos)pos=to;else pos+=context.pos<to?-1:1;}if(!old.settings(after.block(old.path,pos,old.slot)))return false;}return true;}
}
